  it("renvoie 401 sans session", async () => {
    const reponse = await GET(new Request("http://local/api/reservationstudio"));
    expect(reponse.status).toBe(401);
  });

  it("renvoie la liste paginée avec une session valide", async () => {
    const reponse = await GET(requeteAuthentifiee());
    const body = await reponse.json();
    expect(Array.isArray(body.items)).toBe(true);
  });
});
```

