4. API et validation double

Route API CRUD de Enfant (liste paginée + création validée) — `app/api/enfant/route.ts` :
```ts
import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";
import { prisma } from "@/lib/prisma";
import { requireUser } from "@/lib/security/authenticated-request";

const SchemaCreation = z.object({ /* champs métier */ });

export async function GET(request: NextRequest) {
  await requireUser(request);
  const page = Number(new URL(request.url).searchParams.get("page") ?? 1);
  const items = await prisma.enfant.findMany({ orderBy: { createdAt: "desc" }, take: 20, skip: (page - 1) * 20 });
  return NextResponse.json({ items });
}

export async function POST(request: NextRequest) {
  const utilisateur = await requireUser(request);
  const body = SchemaCreation.parse(await request.json());
  const cree = await prisma.enfant.create({ data: { ...body, ownerId: utilisateur.uid } });
  return NextResponse.json(cree, { status: 201 });
}
```

5. Interface : états et accessibilité

Composant liste avec les quatre états d'interface — `components/EnfantListe.tsx` :
```tsx
"use client";
import { useEffect, useState } from "react";

type Etat = { statut: "chargement" } | { statut: "vide" } | { statut: "erreur"; message: string } | { statut: "donnees"; items: { id: string }[] };

export function EnfantListe() {
  const [etat, setEtat] = useState<Etat>({ statut: "chargement" });
  useEffect(() => {
    fetch("/api/enfant")
      .then((r) => (r.ok ? r.json() : Promise.reject(new Error(String(r.status)))))
      .then((body) => setEtat(body.items.length ? { statut: "donnees", items: body.items } : { statut: "vide" }))
      .catch((err) => setEtat({ statut: "erreur", message: err.message }));
  }, []);

  if (etat.statut === "chargement") return <p role="status">Chargement…</p>;
  if (etat.statut === "erreur") return <p role="alert">Erreur : {etat.message}</p>;
  if (etat.statut === "vide") return <p>Aucun élément pour le moment.</p>;
  return (
    <ul>
      {etat.items.map((item) => <li key={item.id}>{/* rendu de la fiche */}</li>)}
    </ul>
  );
}
```Le composant gère les quatre états (chargement, vide, erreur, données) et reste utilisable au clavier seul.

