2. Implémentation

Route API CRUD de Consultation (liste paginée + création validée) — `server/routes/consultation.ts` :
```ts
import { Router } from "express";
import { z } from "zod";
import { requireAuth } from "../middleware/auth.js";

export const routerConsultation = Router();
const SchemaCreation = z.object({ /* champs métier */ });

router.get("/consultation", requireAuth, async (req, res) => {
  const page = Number(req.query.page ?? 1);
  const items = await repo.consultation.lister({ page, parPage: 20 });
  res.json({ items });
});

router.post("/consultation", requireAuth, async (req, res) => {
  const body = SchemaCreation.parse(req.body);
  const cree = await repo.consultation.creer({ ...body, ownerId: req.user.uid });
  res.status(201).json(cree);
});
```

